<?php if(count($data_ujian)): ?><table class="table table-hover table-striped exam-attendance-table"><thead><tr><th width="4%">No</th><th>Mata Kuliah</th><th>UTS</th><th>Absensi UTS</th><th>UAS</th><th>Absensi UAS</th><th>Status UAS</th><th>Keringanan</th></tr></thead><tbody><?php $no=1; ?><?php $__currentLoopData = $data_ujian; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $item): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><?php ($uasAvailable=!empty($item->tgl_uas)); ?><?php ($absenceLimit=$item->id_kelas == 1 ? 3 : 4); ?><?php ($eligibleUas=$uasAvailable && $item->jml_tdk_hdr <= $absenceLimit); ?><tr><td data-label="Mata Kuliah"><?php echo e($no++); ?></td><td data-label="Mata Kuliah"><span class="exam-course"><?php echo e($item->makul); ?></span></td><td data-label="Waktu UTS"><span class="exam-date"><?php echo e($formatTanggalIndonesia($item->tgl_uts)); ?></span></td><td data-label="Absensi UTS"><?php if(is_null($item->absen_uts)): ?><a href="<?php echo e(url('absen_ujian_uts/' . $item->id_studentrecord)); ?>" class="btn btn-success btn-xs exam-action"><i class="fa fa-check"></i> Absen UTS</a><?php else: ?><span class="label label-success exam-status"><i class="fa fa-check"></i> <?php echo e($item->absen_uts); ?></span><?php endif; ?></td><td data-label="Waktu UAS"><span class="exam-date"><?php echo e($formatTanggalIndonesia($item->tgl_uas)); ?></span></td><td data-label="Absensi UAS"><?php if(!$uasAvailable): ?><span class="text-muted">Belum dijadwalkan</span><?php elseif(!is_null($item->absen_uas)): ?><span class="label label-success exam-status"><i class="fa fa-check"></i> <?php echo e($item->absen_uas); ?></span><?php elseif($eligibleUas): ?><a href="<?php echo e(url('absen_ujian_uas_memenuhi/' . $item->id_studentrecord)); ?>" class="btn btn-success btn-xs exam-action"><i class="fa fa-check"></i> Absen UAS</a><?php else: ?><a href="<?php echo e(url('absen_ujian_uas_tdk_memenuhi/' . $item->id_studentrecord)); ?>" class="btn btn-warning btn-xs exam-action"><i class="fa fa-exclamation-triangle"></i> Proses UAS</a><?php endif; ?></td><td data-label="Status UAS"><?php if(!$uasAvailable): ?><span class="label label-default exam-status">Belum tersedia</span><?php elseif($eligibleUas): ?><span class="label label-success exam-status"><i class="fa fa-check"></i> Memenuhi syarat</span><?php else: ?><span class="label label-danger exam-status"><i class="fa fa-times"></i> Tidak memenuhi</span><?php endif; ?></td><td data-label="Keringanan"><?php if($uasAvailable && !$eligibleUas): ?><?php if(is_null($item->permohonan)): ?><a href="<?php echo e(url('ajukan_keringanan_absen/' . $item->id_studentrecord)); ?>" class="btn btn-primary btn-xs exam-action"><i class="fa fa-paper-plane"></i> Ajukan</a><?php elseif($item->permohonan === 'MENGAJUKAN'): ?><span class="label label-warning exam-status"><i class="fa fa-clock-o"></i> Diajukan</span><?php elseif($item->permohonan === 'DISETUJUI'): ?><span class="label label-success exam-status"><i class="fa fa-check"></i> Disetujui</span><?php else: ?><span class="label label-danger exam-status"><i class="fa fa-times"></i> Tidak disetujui</span><?php endif; ?>@else<span class="text-muted">-</span><?php endif; ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></tbody></table><?php else: ?><div class="text-center text-muted" style="padding:35px 15px;"><i class="fa fa-calendar-times-o fa-3x"></i><h4>Belum ada jadwal ujian</h4><p>Jadwal ujian pada periode aktif akan tampil di halaman ini.</p></div><?php endif; ?>
